import assert from "node:assert/strict";
import { test } from "node:test";
import { branchOf, byBranch, isUntagged, matches } from "../src/filter.ts";
import type { EnvctlResource } from "../src/filter.ts";
import { buildPlan } from "../src/plan.ts";
import { summarize } from "../src/report.ts";

function res(id: string, props: Partial<EnvctlResource> = {}): EnvctlResource {
  return {
    id, name: id, type: "volume", tags: {}, stack_id: null, depends_on: [],
    cost_month_cents: 100, created_at: "2024-11-01T00:00:00Z", ...props,
  };
}

test("labels use case-insensitive keys, exact values, and explicit tags take precedence", () => {
  const labelled = res("labelled", { labels: { bRaNcH: "feat-a", Team: "Payments" } });
  assert.equal(branchOf(labelled), "feat-a");
  assert.equal(isUntagged(labelled), false);
  assert.equal(byBranch([labelled]).get("feat-a")?.length, 1);
  assert.doesNotMatch(summarize([labelled]), /untagged/);
  assert.ok(matches(labelled, [["branch", "feat-a"], ["TEAM", "Payments"]]));
  assert.equal(matches(labelled, [["team", "payments"]]), false);
  assert.equal(branchOf(res("both", { tags: { branch: "feat-b" }, labels: { Branch: "feat-a" } })), "feat-b");
  assert.equal(branchOf(res("legacy", { tags: { branch: "feat-a" } })), "feat-a");
  assert.ok(isUntagged(res("no-branch", { labels: { Team: "payments" } })));
});

test("labelled resources and their stack members are selected without expanding to other branches", () => {
  const resources = [
    res("network", { stack_id: "stk-feat-a" }),
    res("volume", { labels: { BRANCH: "feat-a" } }),
    res("instance", { labels: { Branch: "feat-a" }, stack_id: "custom-stack", depends_on: ["network", "volume"] }),
    res("boot", { stack_id: "custom-stack" }),
    res("other", { labels: { Branch: "feat-b" }, stack_id: "stk-feat-a" }),
    res("similar-stack", { stack_id: "stk-feat-a-v2" }),
    res("similar-label", { labels: { Branch: "feat-a-v2" } }),
    res("different-case", { labels: { Branch: "FEAT-A" } }),
    res("orphan"),
  ];
  const plan = buildPlan(resources, "feat-a");
  assert.deepEqual(plan.steps.map(r => r.id).sort(), ["boot", "instance", "network", "volume"]);
  assert.deepEqual(plan.blocked, []);
  const ids = plan.steps.map(r => r.id);
  assert.ok(ids.indexOf("instance") < ids.indexOf("volume"));
  assert.ok(ids.indexOf("instance") < ids.indexOf("network"));
});

test("genuine external label-only dependents still block teardown", () => {
  const plan = buildPlan([
    res("network", { tags: { branch: "feat-a" } }),
    res("external", { labels: { Branch: "feat-b" }, depends_on: ["network"] }),
  ], "feat-a");
  assert.deepEqual(plan.blocked, [{ id: "network", dependents: ["external"] }]);
});
