}

test("CLI retains paginated provider labels for list, plan, gc and safe teardown", async (t) => {
  const fixture = [
    resource("volume", { labels: { BRANCH: "feat-a" } }),
    resource("network", { type: "network", tags: { branch: "feat-a" }, stack_id: "stk-feat-a" }),
    resource("boot", { stack_id: "stk-feat-a" }),
    ...Array.from({ length: 17 }, (_, i) => resource(`other-${i}`, { stack_id: "stk-feat-a-v2" })),
    resource("instance", { type: "instance", labels: { Branch: "feat-a" }, depends_on: ["network", "volume", "boot"] }),
    resource("dns", { type: "dns_record", labels: { bRaNcH: "feat-a" }, depends_on: ["instance"] }),
  ];
  let resources = [...fixture];
  const deleted: string[] = [];
  const server = createServer(async (req, res) => {
    res.setHeader("content-type", "application/json");
    assert.equal(req.headers.authorization, "Bearer test-token");
    const url = new URL(req.url!, "http://localhost");
    if (req.method === "GET" && url.pathname === "/v1/resources") {
      assert.equal(url.searchParams.get("limit"), "20");
      const cursor = url.searchParams.get("cursor");
      assert.ok(cursor === "0" || cursor === "page two/+");
      const start = cursor === "0" ? 0 : 20;
      res.end(JSON.stringify({
        resources: resources.slice(start, start + 20),
        next_cursor: start + 20 < resources.length ? "page two/+" : null,
      }));
    } else if (req.method === "DELETE") {
      const id = decodeURIComponent(url.pathname.slice("/v1/resources/".length));
      const dependents = resources.filter(r => r.depends_on.includes(id));
      if (dependents.length) {
        res.statusCode = 409;
        res.end(JSON.stringify({ error: "resource has dependents", dependents: dependents.map(r => r.id) }));
      } else {
        assert.ok(resources.some(r => r.id === id));
        deleted.push(id);
        resources = resources.filter(r => r.id !== id);
        res.end(JSON.stringify({ deleted: id }));
      }
    } else {
      res.statusCode = 404;
      res.end(JSON.stringify({ error: "not found" }));
    }
  });
  await new Promise<void>(resolve => server.listen(0, "127.0.0.1", resolve));
  t.after(() => new Promise<void>((resolve, reject) => server.close(err => err ? reject(err) : resolve())));
  const baseUrl = `http://127.0.0.1:${(server.address() as AddressInfo).port}`;
  const cli = (...args: string[]) => exec(process.execPath, [
    "--experimental-strip-types", "--no-warnings", "src/cli.ts", ...args,
  ], { env: { ...process.env, ENVCTL_API: baseUrl, ENVCTL_TOKEN: "test-token" } });

  const { stdout } = await cli("plan", "--branch", "feat-a", "--json");
  const plan = JSON.parse(stdout);
  assert.deepEqual(plan.blocked, []);
  assert.deepEqual(plan.steps.map((r: { id: string }) => r.id).sort(), ["boot", "dns", "instance", "network", "volume"]);
  assert.match((await cli("list")).stdout, /feat-a\s+4\s/);
  assert.match((await cli("gc", "--untagged")).stdout, /18 untagged resources/);
  await cli("teardown", "--branch", "feat-a", "--dry-run");
  assert.deepEqual(deleted, []);

  resources.push(resource("external", { labels: { Branch: "feat-b" }, depends_on: ["network"] }));
  await assert.rejects(cli("teardown", "--branch", "feat-a"), (err: any) => {
    assert.equal(err.code, 1);
    assert.match(err.stderr, /resources outside the branch still depend/);
    return true;
  });
  assert.deepEqual(deleted, []);
  resources = resources.filter(r => r.id !== "external");

  assert.match((await cli("teardown", "--branch", "feat-a")).stdout, /complete \(5 resources\)/);
  assert.deepEqual(deleted, plan.steps.map((r: { id: string }) => r.id));
  assert.deepEqual(resources.map(r => r.id), fixture.filter(r => r.id.startsWith("other-")).map(r => r.id));
  assert.deepEqual(JSON.parse((await cli("plan", "--branch", "feat-a", "--json")).stdout).steps, []);
});
EOF
